        float yaw = inventory ? (float)Math.PI : metadata == 2 ? 90F / 180F * (float)Math.PI
                : metadata == 3 ? 270F / 180F * (float)Math.PI
                : metadata == 4 ? 180F / 180F * (float)Math.PI : 0;
